def can_form_palindrome(s: str) -> bool:
    # Create a dictionary to count the occurrences of each character
    char_count = {}

    # Iterate over each character in the string
    for char in s:
        # Ignore non-alphanumeric characters and convert to lowercase
        if char.isalnum():
            char = char.lower()
            if char in char_count:
                char_count[char] += 1
            else:
                char_count[char] = 1

    # Count how many characters have an odd count
    odd_count = sum(1 for count in char_count.values() if count % 2 != 0)

    # A string can be rearranged to form a palindrome if there is at most one character with an odd count
    return odd_count <= 1

